#include <cstdio>
#include <vector>
using namespace std;

static int digitSum(int v) {
    int s = 0;
    for (; v; v /= 10) s += v % 10;
    return s;
}

int main() {
    long long n;
    if (scanf("%lld", &n) != 1) return 0;
    // Every term is in 0..18, so the pair (previous, current) repeats quickly.
    vector<int> values = {0, 1};
    int seen[19][19];
    for (auto &row : seen)
        for (int &x : row) x = -1;
    int a = 0, b = 1;
    while (seen[a][b] < 0) {
        seen[a][b] = (int)values.size() - 1;
        int c = digitSum(a) + digitSum(b);
        a = b;
        b = c;
        values.push_back(b);
    }
    long long start = seen[a][b], period = (long long)values.size() - 1 - start;
    long long index = n < (long long)values.size() ? n : start + (n - start) % period;
    printf("%d\n", values[index]);
}
